var i=`mvc-mvp-and-mvvm`;var o=30;var n={en:[{id:`T030-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`MVC, MVP & MVVM`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Factory Method delegates creation of a product to subclasses or specialized creators; Abstract Factory creates related families of products through a common contract.`},{id:`B`,text:`Unit of Work tracks and coordinates changes that must be persisted together, usually under one transaction.`},{id:`C`,text:`MVC, MVP and MVVM are presentation architecture patterns that separate visual behavior from domain logic in different ways.`},{id:`D`,text:`A Repository presents a collection-like interface for domain objects and hides persistence operations.`}]},{id:`T030-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`MVC, MVP & MVVM`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`MVC routes input through controllers and models; MVP uses a presenter to drive a more passive view; MVVM exposes view state and commands for binding.`},{id:`B`,text:`An implementation tracks new, modified and deleted entities or delegates to an ORM transaction/session.`},{id:`C`,text:`Key GRASP ideas include Information Expert, Creator, Controller, Low Coupling, High Cohesion, Polymorphism, Pure Fabrication, Indirection, and Protected Variations.`},{id:`D`,text:`Choose Factory Method when one creation step varies and Abstract Factory when compatible groups of objects must change together.`}]},{id:`T030-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`That separation matters more than calling it MVVM.`},{id:`B`,text:`Unit tests use a deterministic fake; production wires an SMTP or provider adapter without modifying notification policy.`},{id:`C`,text:`The UI reacts to order-state changes through observers, while the pricing domain need not know about components.`},{id:`D`,text:`A database transaction coordinates the repository updates within one bounded data store.`}]},{id:`T030-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`MVC, MVP & MVVM`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`GoF examples predate modern languages and frameworks.`},{id:`B`,text:`A generic CRUD repository can hide useful database features and create inefficient access.`},{id:`C`,text:`Framework-specific MVC terminology is inconsistent.`},{id:`D`,text:`Injecting every small helper creates boilerplate.`}]},{id:`T030-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`The central difference is how views, controllers/presenters, and state models coordinate.`}]}]},{id:`T030-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`MVC, MVP and MVVM prescribe exactly the same UI dependency direction.`}]}]},{id:`T030-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Avoid moving all decisions into a gigantic presenter or view model; async states, cleanup, accessibility and error handling still need design.`}]}]},{id:`T030-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`MVC, MVP & MVVM`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`View models must contain the database driver to keep presentation logic simple.`},{id:`B`,text:`MVC, MVP and MVVM are presentation architecture patterns that separate visual behavior from domain logic in different ways.`},{id:`C`,text:`MVC routes input through controllers and models; MVP uses a presenter to drive a more passive view; MVVM exposes view state and commands for binding.`},{id:`D`,text:`A repository must expose arbitrary database queries to every consumer.`}]},{id:`T030-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`MVC, MVP & MVVM`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`That separation matters more than calling it MVVM.`},{id:`B`,text:`Unit of Work is useful only when all writes can be split into unrelated commits.`},{id:`C`,text:`MVC, MVP and MVVM prescribe exactly the same UI dependency direction.`},{id:`D`,text:`Avoid moving all decisions into a gigantic presenter or view model; async states, cleanup, accessibility and error handling still need design.`}]},{id:`T030-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to separate data loading, view state, and domain policy on a reservation screen. Compare an MVVM-like approach with a simple smart/presentational component split.`},{id:`B`,text:`Ask an agent to model a reservation repository contract with concurrency-safe save behavior. Review whether every method corresponds to a real workflow and add database integration tests.`},{id:`C`,text:`Give an agent three changing requirements for a document editor. Ask it to choose at most two patterns, explain alternatives, and demonstrate how the design accommodates an added feature.`},{id:`D`,text:`Refactor a service that constructs its own HTTP client and email sender. Have the agent expose only needed dependencies and test retries without network access.`}]},{id:`T030-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which parts of your frontend state are presentation concerns and which are domain invariants?`}]}]},{id:`T030-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`MVC, MVP & MVVM`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T030-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0},{t:` — propose three checks for `},{t:`MVC, MVP & MVVM`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T030-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T030-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`MVC, MVP & MVVM`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An Angular reservation page can keep visual rendering in the component, state derivation in a view-model-like service, and domain booking policy on the backend.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T030-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`MVC, MVP та MVVM`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Factory Method делегує створення продукту спеціалізованому творцю або підкласу; Abstract Factory створює пов’язані сімейства продуктів через спільний контракт.`},{id:`B`,text:`Unit of Work відстежує та координує зміни, які треба зберегти разом, зазвичай у межах однієї транзакції.`},{id:`C`,text:`MVC, MVP та MVVM — патерни архітектури представлення, які по-різному відділяють UI від бізнес-логіки.`},{id:`D`,text:`Repository надає інтерфейс, схожий на колекцію доменних об’єктів, і приховує операції збереження.`}]},{id:`T030-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`MVC, MVP та MVVM`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`MVC обробляє ввід через контролери й моделі; MVP використовує presenter, що керує пасивнішим view; MVVM відкриває стан і команди для binding.`},{id:`B`,text:`Реалізація відстежує нові, змінені й видалені сутності або використовує транзакцію ORM.`},{id:`C`,text:`Основні ідеї GRASP: Information Expert, Creator, Controller, Low Coupling, High Cohesion, Polymorphism, Pure Fabrication, Indirection та Protected Variations.`},{id:`D`,text:`Factory Method доречний, коли змінюється один крок створення, а Abstract Factory — коли потрібно узгоджено створювати групи об’єктів.`}]},{id:`T030-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Це важливіше, ніж назвати підхід MVVM.`},{id:`B`,text:`Юніт-тести використовують детермінований fake; production підключає SMTP або API-провайдера без зміни політики сповіщень.`},{id:`C`,text:`UI реагує на стан замовлення через спостерігачів, а домен цін нічого не знає про компоненти.`},{id:`D`,text:`Транзакція БД координує зміни репозиторіїв у межах одного сховища.`}]},{id:`T030-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`MVC, MVP та MVVM`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Приклади GoF створені до багатьох сучасних мов і фреймворків.`},{id:`B`,text:`Універсальний CRUD-репозиторій може приховувати корисні можливості БД та провокувати неефективні запити.`},{id:`C`,text:`Термін MVC у фреймворках означає різне.`},{id:`D`,text:`Ін’єкція кожного дрібного helper створює шаблонний код.`}]},{id:`T030-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Головна відмінність — взаємодія view, controller/presenter і моделі стану.`}]}]},{id:`T030-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`MVC, MVP і MVVM задають ідентичний напрям залежностей у UI.`}]}]},{id:`T030-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не переносіть усі рішення у величезний presenter чи view model; асинхронні стани, cleanup, доступність і помилки все одно потрібно продумати.`}]}]},{id:`T030-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`MVC, MVP та MVVM`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`View Model мусить містити драйвер БД, щоб UI-логіка була простою.`},{id:`B`,text:`MVC, MVP та MVVM — патерни архітектури представлення, які по-різному відділяють UI від бізнес-логіки.`},{id:`C`,text:`MVC обробляє ввід через контролери й моделі; MVP використовує presenter, що керує пасивнішим view; MVVM відкриває стан і команди для binding.`},{id:`D`,text:`Repository має відкривати довільні запити до БД кожному споживачеві.`}]},{id:`T030-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`MVC, MVP та MVVM`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Це важливіше, ніж назвати підхід MVVM.`},{id:`B`,text:`Unit of Work корисний лише коли всі записи можна виконувати незалежними комітами.`},{id:`C`,text:`MVC, MVP і MVVM задають ідентичний напрям залежностей у UI.`},{id:`D`,text:`Не переносіть усі рішення у величезний presenter чи view model; асинхронні стани, cleanup, доступність і помилки все одно потрібно продумати.`}]},{id:`T030-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента відділити завантаження даних, стан UI та доменні правила на сторінці бронювання. Порівняйте MVVM-подібний підхід із простим поділом на smart/presentational компоненти.`},{id:`B`,text:`Попросіть агента змоделювати контракт репозиторію бронювань із безпечним конкурентним записом. Перевірте, чи кожен метод потрібен сценарію, та додайте інтеграційні тести БД.`},{id:`C`,text:`Дайте агенту три змінні вимоги редактора документів. Попросіть обрати не більше двох патернів, пояснити альтернативи й показати, як додати нову фічу.`},{id:`D`,text:`Відрефакторіть сервіс, який сам створює HTTP-клієнт і відправника листів. Попросіть агента відкрити лише потрібні залежності й перевірити повтори без мережі.`}]},{id:`T030-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Який стан фронтенду належить представленню, а який — доменним інваріантам?`}]}]},{id:`T030-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`MVC, MVP та MVVM`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T030-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0},{t:` запропонуйте три перевірки `},{t:`MVC, MVP та MVVM`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T030-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T030-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`MVC, MVP та MVVM`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`В Angular-сторінці бронювання рендеринг лишається в компоненті, похідний стан — у сервісі на кшталт view model, а правила бронювання — на бекенді.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:30,questions:n};export{r as default,n as questions,i as slug,o as topicId};